<?php
use AISkillsHub\Core\Developers\Frontend as Developers;
use AISkillsHub\Core\Accounts\Strings as AccountStrings;
use AISkillsHub\Core\Contributions\Ui;
use AISkillsHub\Core\Frontend\Router;
use AISkillsHub\Core\Frontend\View;
defined( 'ABSPATH' ) || exit;
$c = Developers::context(); $locale = $c['locale']; $profile = $c['profile'];
$t = static fn( string $key ): string => Developers::t( $key, $locale ); $a = static fn( string $key ): string => AccountStrings::get( $key, $locale );
$public = static fn( string $route ): string => Router::url( $route, array(), $locale );
$url = static fn( string $route, array $query ): string => Developers::url( $route, $locale, $query );
?>
<!doctype html><html lang="<?php echo esc_attr( 'zh_CN' === $locale ? 'zh-CN' : 'en' ); ?>"><head><meta charset="<?php bloginfo( 'charset' ); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#F9FAFB"><?php wp_head(); ?></head>
<body <?php body_class( 'aish-account-site aish-developer-public' ); ?>><?php wp_body_open(); ?><a class="account-skip" href="#developer-main"><?php echo esc_html( $a( 'skip' ) ); ?></a>
<header class="account-site-header"><div class="account-container account-header-inner"><a class="account-brand" href="<?php echo esc_url( $public( 'home' ) ); ?>"><span class="account-brand-symbol" aria-hidden="true"><?php echo View::icon( 'layers' ); ?></span><span>AI Skills <span class="account-muted">Hub</span></span></a><nav class="account-public-nav" aria-label="<?php echo esc_attr( $a( 'explore' ) ); ?>"><a href="<?php echo esc_url( $public( 'skills' ) ); ?>"><?php echo esc_html( $a( 'explore' ) ); ?></a><a href="<?php echo esc_url( $public( 'tutorials' ) ); ?>"><?php echo esc_html( $a( 'tutorials' ) ); ?></a></nav><nav class="account-language" aria-label="<?php echo esc_attr( $a( 'language' ) ); ?>"><?php foreach ( $c['alternatives'] as $language => $link ) : ?><a href="<?php echo esc_url( $link ); ?>" lang="<?php echo esc_attr( 'zh_CN' === $language ? 'zh-CN' : 'en' ); ?>" <?php echo $language === $locale ? 'aria-current="true"' : ''; ?>><?php echo esc_html( 'zh_CN' === $language ? '中' : 'EN' ); ?></a><?php endforeach; ?></nav></div></header>
<main id="developer-main" class="account-main" tabindex="-1"><div class="account-container"><nav class="account-breadcrumb" aria-label="<?php echo esc_attr( $a( 'home' ) ); ?>"><a href="<?php echo esc_url( $public( 'home' ) ); ?>"><?php echo esc_html( $a( 'home' ) ); ?></a><span aria-hidden="true">/</span><span><?php echo esc_html( $t( 'public' ) ); ?></span></nav>
<?php if ( $c['error'] ) : ?><section class="account-panel account-section"><h1><?php echo esc_html( $t( 'public_unavailable' ) ); ?></h1><p><?php echo esc_html( $t( 'unavailable' === $c['error'] ? 'missing_translation' : 'error.' . $c['error'] ) ); ?></p><div class="account-inline-actions"><?php foreach ( $c['alternatives'] as $language => $link ) : ?><a class="account-button account-button-secondary" href="<?php echo esc_url( $link ); ?>"><?php echo esc_html( 'zh_CN' === $language ? '中文' : 'English' ); ?></a><?php endforeach; ?><a class="account-button account-button-primary" href="<?php echo esc_url( $public( 'skills' ) ); ?>"><?php echo esc_html( $a( 'explore' ) ); ?></a></div></section>
<?php else : ?>
<header class="account-panel account-section developer-profile-header"><div class="developer-profile-identity"><span class="account-avatar account-avatar-large" aria-hidden="true"><?php if ( $profile['avatar'] ) : ?><img src="<?php echo esc_url( Developers::url( 'avatar', $locale, array( 'handle' => $profile['handle'] ) ) ); ?>" alt="" width="80" height="80"><?php else : echo View::icon( 'layers' ); endif; ?></span><div><p class="account-eyebrow"><?php echo esc_html( $t( 'public' ) ); ?></p><h1><?php echo esc_html( $profile['display_name'] ); ?></h1></div></div><p class="contributions-copy developer-biography"><?php echo esc_html( $profile['bio'] ); ?></p><div class="account-inline-actions"><?php foreach ( array( 'github_url', 'website_url' ) as $key ) : if ( empty( $profile[ $key ] ) ) { continue; } ?><a class="account-button account-button-secondary" href="<?php echo esc_url( $profile[ $key ], array( 'https' ) ); ?>" rel="nofollow noopener noreferrer"><?php echo esc_html( $t( $key ) ); ?> <?php echo View::icon( 'external' ); ?></a><?php endforeach; ?></div><p class="account-help"><?php echo esc_html( $t( 'attribution_help' ) ); ?></p></header>
<section class="developer-skills"><h2><?php echo esc_html( $t( 'public_skills' ) ); ?></h2><?php if ( ! $profile['skills']['items'] ) : ?><div class="account-panel account-empty"><p><?php echo esc_html( $t( 'no_skills' ) ); ?></p></div><?php endif; ?><div class="developer-skill-grid"><?php foreach ( $profile['skills']['items'] as $skill ) : ?><article class="account-panel contributions-record"><span class="account-badge"><?php echo esc_html( $t( 'role.' . $skill['claim_role'] ) ); ?></span><h3><a class="account-text-action" href="<?php echo esc_url( View::skillUrl( $skill, $locale ) ); ?>"><?php echo esc_html( $skill['title'] ); ?></a></h3><p><?php echo esc_html( $skill['summary'] ?? '' ); ?></p></article><?php endforeach; ?></div><?php Ui::pagination( $profile['skills'], $url, 'public', $c['params'], $t ); ?></section>
<?php if ( ! empty( $profile['contributions'] ) ) : ?><section class="account-panel account-section"><h2><?php echo esc_html( $t( 'public_contributions' ) ); ?></h2><div class="contributions-records"><?php foreach ( $profile['contributions'] as $contribution ) : $skill = $contribution['skill'] ?? $contribution; ?><article class="contributions-record contributions-record-bordered"><span class="account-badge"><?php echo esc_html( $t( 'role.submitter' ) ); ?></span><h3><a class="account-text-action" href="<?php echo esc_url( View::skillUrl( $skill, $locale ) ); ?>"><?php echo esc_html( $skill['title'] ); ?></a></h3></article><?php endforeach; ?></div></section><?php endif; ?>
<?php endif; ?></div></main><footer class="account-site-footer"><div class="account-container"><p>© <?php echo esc_html( gmdate( 'Y' ) ); ?> AI Skills Hub</p><a href="<?php echo esc_url( $public( 'contact' ) ); ?>"><?php echo esc_html( $a( 'contact' ) ); ?></a></div></footer><?php wp_footer(); ?></body></html>
